/**
 * Budget configuration
 */
export type Budget = {
    id: string;
    /**
     * Maximum budget in dollars
     */
    max_limit: number;
    /**
     * Reset duration (e.g., "30s", "5m", "1h", "1d", "1w", "1M", "1Q")
     */
    reset_duration: string;
    /**
     * Window settings the reset duration cannot express. Only valid when reset_duration is quarterly (`1Q`); the API rejects it on any other window.
     *
     */
    reset_config?: {
        /**
         * First month of Q1 as 1-12, so a fiscal year opening in April (4) gives Apr-Jun / Jul-Sep / Oct-Dec / Jan-Mar. Omitted means January. Quarter boundaries repeat every three months, so only the value modulo 3 changes the reset dates: January, April, July and October all reset on calendar quarters and differ only in which quarter is labelled Q1.
         *
         */
        quarter_start_month?: number;
    };
    last_reset: string;
    current_usage: number;
    /**
     * Additional spend added on top of `max_limit` while the override is active. Omitted when no override is set.
     */
    override_amount?: number;
    /**
     * How long the override stays active. `cycles` keeps it active for a finite number of
     * reset windows; `forever` keeps it active until it is removed. Omitted when no override is set.
     *
     */
    override_mode?: 'cycles' | 'forever';
    /**
     * Reset windows the override is still valid for, including the current one. Positive only
     * for `cycles` mode; recomputed from the original grant on every reset, never decremented in place.
     *
     */
    override_cycles_remaining?: number;
    /**
     * Number of reset windows the current `cycles` override was granted for. Immutable for the life of the grant.
     */
    override_cycles_total?: number;
    /**
     * Reset-window boundary at which the current `cycles` override was granted. Immutable for the life of the grant.
     */
    override_anchor_reset?: string;
    /**
     * Team that owns this budget, when the budget is team-scoped
     */
    team_id?: string;
    /**
     * Virtual key that owns this budget, when the budget is virtual-key-scoped
     */
    virtual_key_id?: string;
    /**
     * Provider config that owns this budget, when the budget is provider-config-scoped
     */
    provider_config_id?: number;
    config_hash: string | null;
    created_at: string;
    updated_at: string;
};

